     1	/**
     2	 * Ambient module declarations for @salesforce/retail-react-app.
     3	 *
     4	 * This package ships without TypeScript types. We declare the modules we
     5	 * import in overrides/ with real types where we know the shape, and fall
     6	 * back to an untyped catch-all for everything else.
     7	 *
     8	 * Add specific declarations here as more subpaths are consumed in overrides/.
     9	 */
    10	
    11	declare module '@salesforce/retail-react-app/app/theme' {
    12	  import type { ChakraTheme } from '@chakra-ui/react';
    13	  const theme: ChakraTheme;
    14	  export default theme;
    15	}
    16	
    17	// Matches the pinned react-router-dom 5.3.4 (see package.json) — the package ships
    18	// without its own types and no @types/react-router-dom is installed, so this mirrors
    19	// that version's real shapes (history's Location/LocationDescriptor, match) rather
    20	// than a generic approximation.
    21	declare module 'react-router-dom' {
    22	  import type React from 'react';
    23	
    24	  interface Location<TState = unknown> {
    25	    pathname: string;
    26	    search: string;
    27	    hash: string;
    28	    state: TState;
    29	    key?: string;
    30	  }
    31	  export function useLocation<TState = unknown>(): Location<TState>;
    32	
    33	  // history 4.x, as bundled by react-router-dom 5.3.4. Only the members consumed in
    34	  // overrides/ are declared — push is used by the footer's wordmark handler.
    35	  interface History<TState = unknown> {
    36	    push(path: string, state?: TState): void;
    37	    replace(path: string, state?: TState): void;
    38	    goBack(): void;
    39	    location: Location<TState>;
    40	  }
    41	  export function useHistory<TState = unknown>(): History<TState>;
    42	
    43	  // Every declared param is optional — a route pattern doesn't guarantee a segment
    44	  // was actually present in the matched URL. Default is `{}` in the real react-router
    45	  // types (so an unparameterised useParams()'s properties correctly fail to resolve);
    46	  // `NonNullable<unknown>` is the eslint-approved equivalent — our ban-types rule
    47	  // rejects a literal `{}`, and `Record<string, never>` was tried and rejected in
    48	  // review: it types every property as `never`, which is assignable to anything and
    49	  // so silently passes property access that should be a compile error.
    50	  export function useParams<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>>(): TParams;
    51	
    52	  type To<TState = unknown> = string | { pathname?: string; search?: string; hash?: string; state?: TState };
    53	
    54	  interface LinkProps<TState = unknown> extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
    55	    to: To<TState>;
    56	    replace?: boolean;
    57	  }
    58	  export const Link: React.ForwardRefExoticComponent<LinkProps & React.RefAttributes<HTMLAnchorElement>>;
    59	
    60	  interface match<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>> {
    61	    params: TParams;
    62	    isExact: boolean;
    63	    path: string;
    64	    url: string;
    65	  }
    66	
    67	  interface NavLinkProps extends LinkProps {
    68	    exact?: boolean;
    69	    activeClassName?: string;
    70	    activeStyle?: React.CSSProperties;
    71	    isActive?: (match: match | null, location: Location) => boolean;
    72	  }
    73	  export const NavLink: React.ForwardRefExoticComponent<NavLinkProps & React.RefAttributes<HTMLAnchorElement>>;
    74	
    75	  // Test-only: wraps a component tree in a router without touching the real browser history.
    76	  // Used by component tests exercising useHistory/useLocation (e.g. footer/index.test.tsx).
    77	  interface MemoryRouterProps<TState = unknown> {
    78	    initialEntries?: ReadonlyArray<string | To<TState>>;
    79	    initialIndex?: number;
    80	    children?: React.ReactNode;
    81	  }
    82	  export const MemoryRouter: React.FC<MemoryRouterProps>;
    83	}
    84	
    85	declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/utils' {
    86	  export function getAssetUrl(path: string): string;
    87	}
    88	
    89	declare module '@salesforce/pwa-kit-runtime/utils/ssr-config' {
    90	  export function getConfig(): { app: Record<string, unknown> };
    91	}
    92	
    93	declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks' {
    94	  type ServerResponse = {
    95	    set: (name: string, value: string) => void;
    96	    status: (code: number) => ServerResponse;
    97	  };
    98	  export function useServerContext(): {
    99	    req?: any;
   100	    res?: ServerResponse;
   101	  };
   102	  export function useCorrelationId(): { correlationId: string };
   103	}
   104	
   105	declare module '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths' {
   106	  export const getEnvBasePath: () => string;
   107	  export const slasPrivateProxyPath: string;
   108	  export const bundleBasePath: string;
   109	}
   110	
   111	declare module '@salesforce/pwa-kit-runtime/utils/logger-factory' {
   112	  const createLogger: (opts: { packageName: string }) => any;
   113	  export default createLogger;
   114	}
   115	
   116	declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query' {
   117	  export function withReactQuery(Component: any, options?: any): any;
   118	}
   119	
   120	declare module '@salesforce/pwa-kit-react-sdk/utils/url' {
   121	  export function getAppOrigin(): string;
   122	}
   123	
   124	declare module '@loadable/component' {
   125	  const loadable: (fn: () => Promise<any>, opts?: any) => any;
   126	  export default loadable;
   127	}
   128	
   129	// Static asset imports (webpack url-loader / asset modules)
   130	declare module '*.svg' {
   131	  const src: string;
   132	  export default src;
   133	}
   134	
   135	// react-helmet 6.1.0 ships no types and @types/react-helmet is not installed (adding a
   136	// package needs Integration approval — see AGENTS.md Hard Rule #7). This declares the
   137	// surface overrides/ actually uses: <Helmet> with element children.
   138	declare module 'react-helmet' {
   139	  import type React from 'react';
   140	
   141	  interface HelmetProps {
   142	    children?: React.ReactNode;
   143	    defer?: boolean;
   144	    encodeSpecialCharacters?: boolean;
   145	    htmlAttributes?: Record<string, string>;
   146	    bodyAttributes?: Record<string, string>;
   147	    titleTemplate?: string;
   148	    defaultTitle?: string;
   149	  }
   150	
   151	  export const Helmet: React.ComponentType<HelmetProps>;
   152	  export default Helmet;
   153	}
   154	
   155	// Mirrors node_modules/@salesforce/pwa-kit-react-sdk/ssr/universal/errors.js. `status` is
   156	// optional on the constructor because callers derive it from an API response that may not
   157	// carry one — the base retail-react-app PDP passes a possibly-undefined status through.
   158	declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/errors' {
   159	  export class HTTPError extends Error {
   160	    constructor(status?: number, message?: string);
   161	    status?: number;
   162	    toString(): string;
   163	  }
   164	
   165	  export class HTTPNotFound extends HTTPError {
   166	    constructor(message?: string);
   167	  }
   168	}
   169	
   170	// Catch-all for all other @salesforce/retail-react-app subpaths not declared above.
   171	declare module '@salesforce/retail-react-app/*';
   172	
   173	// @vitejs/plugin-react uses package exports only (no root index.d.ts), which
   174	// TypeScript 4.9 with moduleResolution:node cannot resolve. Minimal shim — the
   175	// actual Plugin return type depends on vite types that are equally unreachable
   176	// from TS 4.9. Once the project upgrades to TS 5+ this declaration can be removed.
   177	declare module '@vitejs/plugin-react' {
   178	  interface Options {
   179	    include?: string | RegExp | Array<string | RegExp>;
   180	    exclude?: string | RegExp | Array<string | RegExp>;
   181	    jsxImportSource?: string;
   182	  }
   183	  // Return typed as any: Plugin from vite is not resolvable under moduleResolution:node.
   184	  function react(options?: Options): any;
   185	  export default react;
   186	}

